import{_ as e,o as d,c as s,a2 as a}from"./chunks/framework.BCI0HzK1.js";const k=JSON.parse('{"title":"版本与时效说明","description":"本站对齐的 NestJS 版本、工具链与官方更新后的自查方法。","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"guide/version.md","filePath":"guide/version.md","lastUpdated":1794299341000}'),i={name:"guide/version.md"};function o(n,t,r,c,l,h){return d(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="版本与时效说明" tabindex="-1">版本与时效说明 <a class="header-anchor" href="#版本与时效说明" aria-label="Permalink to &quot;版本与时效说明&quot;">​</a></h1><p class="search-summary-seed" aria-hidden="true">本站对齐的 NestJS 版本、工具链与官方更新后的自查方法。</p><p>本页说明教程对齐的版本、这些版本是怎么核对出来的，以及官方升级后你应该怎么自查差异。<strong>所有版本号都来自本仓库实际安装结果，不是凭印象写的。</strong></p><p>最后核对时间：<strong>2026-11-10</strong>（核对方式见文末）。</p><h2 id="一、当前对齐的版本" tabindex="-1">一、当前对齐的版本 <a class="header-anchor" href="#一、当前对齐的版本" aria-label="Permalink to &quot;一、当前对齐的版本&quot;">​</a></h2><p>主版本：<strong>NestJS 12</strong></p><table tabindex="0"><thead><tr><th>包 / 工具</th><th>实际安装版本</th><th>作用</th><th>需要关注的变更</th></tr></thead><tbody><tr><td><code>@nestjs/core</code> / <code>@nestjs/common</code> / <code>@nestjs/platform-express</code></td><td>12.4.2</td><td>框架核心</td><td><strong>12 起为纯 ESM 包</strong>（<code>&quot;type&quot;: &quot;module&quot;</code>）</td></tr><tr><td><code>@nestjs/cli</code></td><td>12.0.12</td><td>脚手架与构建</td><td>生成的模板改为 ESM + <code>.js</code> 后缀导入</td></tr><tr><td><code>@nestjs/schematics</code></td><td>12.0.13</td><td><code>nest g</code> 代码生成</td><td>要求 TypeScript <code>&gt;= 6</code></td></tr><tr><td><code>@nestjs/config</code></td><td>12.1.1</td><td>配置模块</td><td>第 05 章使用</td></tr><tr><td><code>@nestjs/typeorm</code> / <code>typeorm</code></td><td>12.0.3 / 1.1.2</td><td>ORM 与 Nest 集成</td><td>第 04 章使用；生产必须关闭 <code>synchronize</code></td></tr><tr><td><code>pg</code></td><td>8.23.1</td><td>Postgres 驱动</td><td>连接池、SSL 行为由驱动决定</td></tr><tr><td><code>sql.js</code></td><td>1.15.2</td><td>测试用内存数据库</td><td>第 04 章使用；方言与 Postgres 不完全一致</td></tr><tr><td><code>@nestjs/jwt</code></td><td>12.0.4</td><td>JWT 签发与校验</td><td>第 06 章使用</td></tr><tr><td><code>postgres</code>（Docker 镜像）</td><td>17</td><td>本地开发数据库</td><td>迁移用到 <code>gen_random_uuid()</code>（PG 13+ 内置）</td></tr><tr><td><code>ioredis</code></td><td>5.11.1</td><td>Redis 客户端</td><td>第 07 章；版本落在 TypeORM peer 范围 <code>^5</code> 内，避免双版本告警</td></tr><tr><td><code>bullmq</code></td><td>6.7.3</td><td>队列与任务调度</td><td>第 08 章；v5 起用 <code>upsertJobScheduler</code> 取代 repeatable jobs</td></tr><tr><td><code>redis</code>（Docker 镜像）</td><td>7</td><td>本地缓存与队列</td><td>compose 中开启 AOF，队列任务重启不丢</td></tr><tr><td><code>@nestjs/mapped-types</code></td><td>12.0.1</td><td><code>PartialType</code> 等 DTO 工具</td><td>第 03 章使用</td></tr><tr><td><code>@nestjs/testing</code></td><td>12.4.2</td><td>测试容器</td><td>第 12 章使用</td></tr><tr><td><code>typescript</code></td><td>6.0.3</td><td>编译器</td><td><code>isolatedModules</code> 下装饰器签名需 <code>import type</code></td></tr><tr><td><code>@types/node</code></td><td>24.19.2</td><td>Node 类型</td><td>与本地 Node 24 对齐</td></tr><tr><td><code>vitest</code> / <code>@vitest/coverage-v8</code></td><td>5.1.0</td><td>测试运行器</td><td>官方模板默认用 Vitest 取代 Jest</td></tr><tr><td><code>supertest</code></td><td>7.3.2</td><td>HTTP 断言</td><td>e2e 使用</td></tr><tr><td><code>class-validator</code> / <code>class-transformer</code></td><td>0.15.1 / 0.5.1</td><td>DTO 校验与转换</td><td>第 03 章使用</td></tr><tr><td><code>rxjs</code> / <code>reflect-metadata</code></td><td>7.8.2 / 0.2.2</td><td>拦截器数据流 / 元数据</td><td>框架必需</td></tr><tr><td><code>eslint</code> / <code>typescript-eslint</code></td><td>10.14.0 / 8.72.2</td><td>静态检查</td><td>ESLint 10 只支持 flat config</td></tr><tr><td><code>vitepress</code></td><td>1.6.4</td><td>本站</td><td>支持 <code>&lt;&lt;&lt;</code> 片段与 region</td></tr></tbody></table><p>运行时要求：Node.js <code>&gt;= 22.12.0</code>（Vitest 5 的下限；NestJS 12 自身要求 <code>&gt;= 20</code>）。本仓库开发环境为 Node 24.17.0 + pnpm 10.15.0。</p><h2 id="二、nestjs-12-三个会影响写法的事实" tabindex="-1">二、NestJS 12 三个会影响写法的事实 <a class="header-anchor" href="#二、nestjs-12-三个会影响写法的事实" aria-label="Permalink to &quot;二、NestJS 12 三个会影响写法的事实&quot;">​</a></h2><p>这三点都不是「新特性」，而是<strong>会直接让你复制旧教程代码报错</strong>的变化：</p><h3 id="_1-纯-esm" tabindex="-1">1. 纯 ESM <a class="header-anchor" href="#_1-纯-esm" aria-label="Permalink to &quot;1. 纯 ESM&quot;">​</a></h3><p><code>@nestjs/common</code> 的 <code>package.json</code> 里是 <code>&quot;type&quot;: &quot;module&quot;</code>，没有 CommonJS 入口。后果：</p><ul><li>工程要写 <code>&quot;type&quot;: &quot;module&quot;</code>；</li><li>相对导入必须带 <code>.js</code> 后缀（哪怕源文件是 <code>.ts</code>）；</li><li>只支持 CommonJS 的测试器（如传统 Jest 配置）会报 <code>ERR_REQUIRE_ESM</code>，示例改用 Vitest；</li><li><code>__dirname</code> 不可用，需要时用 <code>import.meta.url</code> 换算。</li></ul><h3 id="_2-官方模板的-tsconfig-是-nodenext" tabindex="-1">2. 官方模板的 tsconfig 是 <code>nodenext</code> <a class="header-anchor" href="#_2-官方模板的-tsconfig-是-nodenext" aria-label="Permalink to &quot;2. 官方模板的 tsconfig 是 \`nodenext\`&quot;">​</a></h3><p>关键项：<code>module: &quot;nodenext&quot;</code>、<code>moduleResolution: &quot;nodenext&quot;</code>、<code>isolatedModules: true</code>、<code>target: &quot;ES2023&quot;</code>。 在 <code>isolatedModules + emitDecoratorMetadata</code> 同时开启时，<strong>装饰器签名里引用的类型必须用 <code>import type</code> 导入</strong>，否则编译器报 <code>TS1272</code>。示例代码里 DTO、Controller 的返回类型都按这个规则写。</p><h3 id="_3-脚手架默认工具链换成了-vitest-oxlint" tabindex="-1">3. 脚手架默认工具链换成了 Vitest + oxlint <a class="header-anchor" href="#_3-脚手架默认工具链换成了-vitest-oxlint" aria-label="Permalink to &quot;3. 脚手架默认工具链换成了 Vitest + oxlint&quot;">​</a></h3><p>用 <code>@nestjs/cli</code> 12 生成的新项目，<code>package.json</code> 里测试是 <code>vitest run</code>、Lint 是 <code>oxlint</code>。本仓库<strong>测试用 Vitest</strong>（与官方一致），<strong>Lint 用 ESLint</strong>（生态更成熟、规则可读性更好），属于有意识的取舍，不是照抄模板。</p><h2 id="三、官方更新后怎么自查" tabindex="-1">三、官方更新后怎么自查 <a class="header-anchor" href="#三、官方更新后怎么自查" aria-label="Permalink to &quot;三、官方更新后怎么自查&quot;">​</a></h2><p>按下面的顺序做，10 分钟内能得到「我的教程/项目哪里会坏」。</p><h3 id="步骤-1-看本仓库实际装了什么" tabindex="-1">步骤 1：看本仓库实际装了什么 <a class="header-anchor" href="#步骤-1-看本仓库实际装了什么" aria-label="Permalink to &quot;步骤 1：看本仓库实际装了什么&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @nestjs-tutorial/api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --depth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><h3 id="步骤-2-看远端最新版本" tabindex="-1">步骤 2：看远端最新版本 <a class="header-anchor" href="#步骤-2-看远端最新版本" aria-label="Permalink to &quot;步骤 2：看远端最新版本&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @nestjs/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @nestjs/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> engines</span></span></code></pre></div><p>官方发布记录里重点看两件事：<strong>主版本号是否变化</strong>、<strong>是否出现 breaking change 标注</strong>。</p><h3 id="步骤-3-用官方模板做对照实验" tabindex="-1">步骤 3：用官方模板做对照实验 <a class="header-anchor" href="#步骤-3-用官方模板做对照实验" aria-label="Permalink to &quot;步骤 3：用官方模板做对照实验&quot;">​</a></h3><p>这是最可靠的一步——直接看官方此刻怎么配置一个新项目：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @nestjs/cli@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ref-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --package-manager</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ref-app/package.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ref-app/tsconfig.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ref-app</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 看测试配置文件叫什么</span></span></code></pre></div><p>对照下面四项，任何一项不同，本教程相关章节就要复核：</p><table tabindex="0"><thead><tr><th>对照项</th><th>本教程的取值</th><th>不同意味着什么</th></tr></thead><tbody><tr><td><code>package.json</code> 是否有 <code>&quot;type&quot;: &quot;module&quot;</code></td><td>有</td><td>若取消，<code>.js</code> 后缀与 Vitest 选择都要重估</td></tr><tr><td><code>tsconfig.json</code> 的 <code>module</code> / <code>moduleResolution</code></td><td><code>nodenext</code> / <code>nodenext</code></td><td>若改回 <code>commonjs</code>，第 01 章的导入规则整节失效</td></tr><tr><td>测试运行器</td><td>Vitest</td><td>若换回 Jest，第 12 章要重写</td></tr><tr><td>装饰器相关编译选项</td><td><code>emitDecoratorMetadata</code> + <code>experimentalDecorators</code></td><td>若改用标准装饰器，全书的 DI 写法都要复核</td></tr></tbody></table><h3 id="步骤-4-跑一遍本仓库门禁" tabindex="-1">步骤 4：跑一遍本仓库门禁 <a class="header-anchor" href="#步骤-4-跑一遍本仓库门禁" aria-label="Permalink to &quot;步骤 4：跑一遍本仓库门禁&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p><code>verify</code> 覆盖 lint、类型检查、单测、e2e、构建与文档构建。升级依赖后如果它仍然全绿，说明写作层面的结论大概率还成立；红了就先修代码，再回来改文档。</p><h3 id="步骤-5-确认-esm-这一条是否仍成立" tabindex="-1">步骤 5：确认 ESM 这一条是否仍成立 <a class="header-anchor" href="#步骤-5-确认-esm-这一条是否仍成立" aria-label="Permalink to &quot;步骤 5：确认 ESM 这一条是否仍成立&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;const p=require(&#39;@nestjs/common/package.json&#39;);console.log(p.type, p.exports)&quot;</span></span></code></pre></div><p>输出 <code>module</code> 说明仍是纯 ESM，第 01 章关于 <code>.js</code> 后缀、<code>import type</code>、Vitest 的结论继续有效。</p><h2 id="四、本教程刻意不写的东西" tabindex="-1">四、本教程刻意不写的东西 <a class="header-anchor" href="#四、本教程刻意不写的东西" aria-label="Permalink to &quot;四、本教程刻意不写的东西&quot;">​</a></h2><table tabindex="0"><thead><tr><th>不写</th><th>原因</th></tr></thead><tbody><tr><td>具体性能数字（QPS、耗时对比）</td><td>没有在同一台机器、同一负载下实测过；只在第 07 章讲机制与测量方法</td></tr><tr><td>「某版本之后才支持」的模糊说法</td><td>除非能在官方发布记录里指到具体条目，否则不写</td></tr><tr><td>平台限制（连接数、文件大小上限）</td><td>与部署环境强相关，放到第 13 章讲如何实测</td></tr><tr><td>未实现的业务代码</td><td>企业级业务页会明确标注「设计讲解，示例未实现」</td></tr></tbody></table><h2 id="五、更新本页的流程" tabindex="-1">五、更新本页的流程 <a class="header-anchor" href="#五、更新本页的流程" aria-label="Permalink to &quot;五、更新本页的流程&quot;">​</a></h2><ol><li>升级依赖，<code>pnpm verify</code> 全绿；</li><li>按上面的「步骤 3」重做一次模板对照；</li><li>更新本页版本表、<code>最后核对时间</code>、以及受影响章节的 <code>ChapterMeta</code>；</li><li>如果变化影响写法（如 ESM、装饰器），同步修改相关章节正文，而不是只改版本号。</li></ol>`,39)])])}const g=e(i,[["render",o]]);export{k as __pageData,g as default};
